#!/bin/bash
# Host-side check (no NeuronCores) of the per-request `request_metrics {json}` stderr line (runtime/src/server.cpp):
# runs neuron_server_fake (built by host_test.sh) on the CPU fake model with a tiny generated byte-level tokenizer and
# asserts one line per request (non-stream, stream, concurrent, client disconnect) with sane fields, that no prompt or
# completion text reaches the log, that `timings` sits next to `usage`, and that BEHEMOTH_REQUEST_LOG=0 silences the line.
#   neuron/cpp/request_metrics_test.sh [OUTDIR with neuron_server_fake, default build-host]
set -e
OUT=$(cd "${1:-build-host}" && pwd)
exec python3 -I - "$OUT/neuron_server_fake" <<'PY'
import json, os, signal, socket, subprocess, sys, tempfile, threading, time, urllib.request

binary = sys.argv[1]
work = tempfile.mkdtemp()
# byte-level BPE without merges: ids 0..255 are the GPT-2 byte symbols, then the control tokens
bs = list(range(33, 127)) + list(range(161, 173)) + list(range(174, 256))
cs, n = bs[:], 0
for b in range(256):
    if b not in bs:
        bs.append(b); cs.append(256 + n); n += 1
sym = dict(zip(bs, cs))
vocab = {chr(sym[b]): b for b in range(256)}
added = ["<|endoftext|>", "<|system|>", "<|user|>", "<|assistant|>"]
json.dump({"version": "1.0", "truncation": None, "padding": None, "normalizer": None,
           "pre_tokenizer": {"type": "ByteLevel", "add_prefix_space": False, "trim_offsets": True, "use_regex": True},
           "post_processor": None, "decoder": {"type": "ByteLevel", "add_prefix_space": True, "trim_offsets": True, "use_regex": True},
           "added_tokens": [{"id": 256 + i, "content": t, "single_word": False, "lstrip": False, "rstrip": False,
                             "normalized": False, "special": True} for i, t in enumerate(added)],
           "model": {"type": "BPE", "vocab": vocab, "merges": [], "ignore_merges": True}}, open(work + "/tokenizer.json", "w"))
json.dump({"eos_token": "<|endoftext|>", "tokenizer_class": "TokenizersBackend"}, open(work + "/tokenizer_config.json", "w"))
json.dump({"vocab_size": 300, "eos_token_id": 256}, open(work + "/config.json", "w"))
open(work + "/chat_template.jinja", "w").write(
    "{% for m in messages %}<|{{ m.role }}|>{{ m.content }}{% endfor %}{% if add_generation_prompt %}<|assistant|>{% endif %}")

def start(extra_env):
    s = socket.socket(); s.bind(("127.0.0.1", 0)); port = s.getsockname()[1]; s.close()
    log = open(work + "/stderr-%d.log" % port, "w+")
    env = dict(os.environ, BEHEMOTH_NEURON_NEFF_DIR=work, BEHEMOTH_FAKE_STEP_MS="20", **extra_env)
    p = subprocess.Popen([binary, "--model", work, "--port", str(port)], stderr=log, env=env)
    for _ in range(100):
        try: urllib.request.urlopen("http://127.0.0.1:%d/health" % port); break
        except Exception: time.sleep(0.1)
    else: raise AssertionError("server did not start")
    return p, port, log

def post(port, body, stream=False):
    req = urllib.request.Request("http://127.0.0.1:%d/v1/chat/completions" % port, json.dumps(body).encode(),
                                 {"Content-Type": "application/json", "Authorization": "Bearer sk-SECRET-KEY"})
    raw = urllib.request.urlopen(req).read().decode()
    return raw if stream else json.loads(raw)

def lines(log):
    log.flush(); log.seek(0)
    return [json.loads(l[len("request_metrics "):]) for l in log.read().splitlines() if l.startswith("request_metrics ")]

def wait_lines(log, count):
    for _ in range(100):
        got = lines(log)
        if len(got) >= count: return got
        time.sleep(0.1)
    return lines(log)

SECRET_PROMPT, checks = "zebra-quartz-prompt-text", 0
def check(cond, what):
    global checks; checks += 1
    assert cond, what

p, port, log = start({})
try:
    # 1. non-streaming: one line, sane fields, `timings` next to `usage`
    r = post(port, {"messages": [{"role": "user", "content": SECRET_PROMPT}], "max_tokens": 6})
    got = wait_lines(log, 1); check(len(got) == 1, "one line for one request")
    m = got[0]; print("example:", "request_metrics " + json.dumps(m, sort_keys=True))
    check(m["id"] == r["id"] and m["status"] == "ok" and m["stream"] is False, "id/status/stream")
    check(m["prompt_tokens"] == r["usage"]["prompt_tokens"] and m["completion_tokens"] == r["usage"]["completion_tokens"] == 6, "tokens match usage")
    check(m["finish_reason"] == r["choices"][0]["finish_reason"] == "length" and m["cached_tokens"] == 0, "finish_reason / cached")
    check(0 <= m["queue_wait_ms"] <= m["ttft_ms"] <= m["total_ms"], "queue_wait <= ttft <= total")
    check(abs(m["prefill_ms"] - (m["ttft_ms"] - m["queue_wait_ms"])) < 0.02 and m["prefill_tokens_per_s"] > 0, "prefill")
    check(m["decode_ms"] >= 15 and 0 < m["decode_tokens_per_s"] <= 5 / 0.015, "decode: at least one 20 ms step after the first token")
    check(m["active_start"] == 1 and m["active_end"] == 1 and m["ts"].endswith("Z"), "active / ts")
    check(r["timings"]["ttft_ms"] == m["ttft_ms"] and r["timings"]["queue_wait_ms"] == m["queue_wait_ms"], "timings in response")
    check(set(r["usage"]) == {"prompt_tokens", "completion_tokens", "total_tokens", "prompt_tokens_details"}, "usage unchanged")
    # 2. streaming with and without include_usage: one line each; usage chunk carries timings
    s = post(port, {"messages": [{"role": "user", "content": SECRET_PROMPT}], "max_tokens": 4, "stream": True,
                    "stream_options": {"include_usage": True}}, stream=True)
    chunks = [json.loads(l[6:]) for l in s.splitlines() if l.startswith("data: {")]
    check(any("timings" in c and "usage" in c for c in chunks), "final usage chunk has timings")
    post(port, {"messages": [{"role": "user", "content": "x"}], "max_tokens": 3, "stream": True}, stream=True)
    got = wait_lines(log, 3); check(len(got) == 3 and got[1]["stream"] and got[2]["stream"] and got[2]["completion_tokens"] == 3, "stream lines")
    # 3. concurrent requests: the later ones see others in flight
    ts = [threading.Thread(target=post, args=(port, {"messages": [{"role": "user", "content": "c%d" % i}], "max_tokens": 8})) for i in range(3)]
    [t.start() for t in ts]; [t.join() for t in ts]
    got = wait_lines(log, 6); check(len(got) == 6 and len({g["id"] for g in got}) == 6, "one line per concurrent request")
    check(max(g["active_start"] for g in got[3:]) >= 2 and all(g["active_end"] >= 1 for g in got), "concurrency counted")
    # 4. client disconnect mid-generation: status cancelled
    c = socket.create_connection(("127.0.0.1", port)); body = json.dumps({"messages": [{"role": "user", "content": "d"}], "max_tokens": 200, "stream": True}).encode()
    c.sendall(b"POST /v1/chat/completions HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\nContent-Length: %d\r\n\r\n" % len(body) + body)
    time.sleep(0.5); c.close()
    got = wait_lines(log, 7); check(len(got) == 7 and got[6]["status"] == "cancelled" and got[6]["finish_reason"] == "client_disconnect", "disconnect")
    check(got[6]["completion_tokens"] < 200, "disconnect before the end")
    time.sleep(0.5); check(len(lines(log)) == 7, "no duplicate lines")
    text = open(log.name).read()
    check(SECRET_PROMPT not in text and "sk-SECRET" not in text and r["choices"][0]["message"]["content"] not in text, "no prompt, completion or key in the log")
finally:
    p.send_signal(signal.SIGTERM); p.wait()
# 5. switch off
p, port, log = start({"BEHEMOTH_REQUEST_LOG": "0"})
try:
    r = post(port, {"messages": [{"role": "user", "content": "x"}], "max_tokens": 2}); time.sleep(0.3)
    check(lines(log) == [] and "timings" in r, "BEHEMOTH_REQUEST_LOG=0 silences the line")
finally:
    p.send_signal(signal.SIGTERM); p.wait()
print("PASS request_metrics: %d checks" % checks)
PY
